class Solution { public String[] generateParentheses(int n) { java.util.ArrayList<String> level=new java.util.ArrayList<>();level.add("");for(int len=0;len<2*n;len++){java.util.ArrayList<String> next=new java.util.ArrayList<>();for(String s:level){int open=0,close=0;for(char c:s.toCharArray())if(c=='(')open++;else close++;if(open<n)next.add(s+"(");if(close<open)next.add(s+")");}level=next;}java.util.Collections.sort(level);return level.toArray(new String[0]); } }
